    const out = { tap: [], tiny: [], contrast: [], unknownContrast: 0, headings: [], emptyLinks: [], unlabeled: [], duplicateIds: [], brokenImages: [], noAlt: [], meta: {} };
    const cap = (list, item) => { if (list.length < 8) list.push(item); };
